def main():
    data = []
    for dialog in DIALOGS:
        messages = [{"role": r, "content": c} for (r, c) in dialog]
        data.append({"category": CATEGORY, "source": SOURCE, "dialog": messages})
    OUT_FILE.write_text(
        json.dumps(data, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    print(f"{len(data)} diyalog yazildi -> {OUT_FILE}")


if __name__ == "__main__":
    main()
